// ============================================================
// SYLLABABBLER v2 — ENGINE
// ============================================================

// Build a flat lookup of every surface form -> morpheme entry.
// Longer forms first so the segmenter prefers maximal matches.
function buildIndex(MORPHEMES) {
  const all = [];
  for (const cls of ["prefixes", "roots", "suffixes"]) {
    for (const m of MORPHEMES[cls]) {
      const forms = [m.form.replace(/\d+$/, ""), ...m.variants];
      for (const f of forms) {
        if (!f) continue;
        all.push({ surface: f.toLowerCase(), cls, ...m, form: m.form.replace(/\d+$/, "") });
      }
    }
  }
  // dedupe by surface, keep entry with the most tags
  const bySurface = {};
  for (const e of all) {
    if (!bySurface[e.surface] || e.tags.length > bySurface[e.surface].tags.length) {
      bySurface[e.surface] = e;
    }
  }
  const list = Object.values(bySurface).sort((a, b) => b.surface.length - a.surface.length);
  return list;
}

