// tide / drift / percussion had no route into the lattice at all
(function widenTags() {
  const add = (form, tags) => {
    const e = MORPHEMES.roots.find(r => r.form === form);
    if (e) e.tags = [...new Set([...e.tags, ...tags])];
  };
  add("rhythm", ["percussion","drum","drumming","pulsation","tempo"]);
  add("chron",  ["duration","clock","tempo"]);
  add("phon",   ["audio","sonic","noise","tone"]);
  add("hydr",   ["ocean","sea","tide","marine","liquid"]);
  add("aqu",    ["ocean","sea","tide","marine","liquid"]);
  add("mov",    ["drift","motion","travel","migration"]);
  add("flu",    ["drift","current","stream","tide","flux"]);
})();
