// merge, dropping anything already present by form or by surface variant
(function mergeExpansion() {
  const taken = new Set();
  for (const cls of ["prefixes", "roots", "suffixes"]) {
    for (const m of MORPHEMES[cls]) {
      taken.add(m.form.toLowerCase());
      for (const v of (m.variants || [])) taken.add(v.toLowerCase());
    }
  }
  let added = 0;
  for (const e of EXPANSION) {
    if (taken.has(e.form.toLowerCase())) continue;
    const variants = (e.variants || []).filter(v => !taken.has(v.toLowerCase()));
    MORPHEMES.roots.push({ ...e, variants });
    taken.add(e.form.toLowerCase());
    for (const v of variants) taken.add(v.toLowerCase());
    added++;
  }
  MORPHEMES.expansionAdded = added;
})();
